#!/usr/bin/env Rscript

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 2) stop("usage: rank_retina_depletion.R marker_report ranking")

lines <- readLines(args[1], warn = FALSE)
start <- grep("^## per-sample core-marker summary$", lines)
if (length(start) != 1L) stop("core-marker section not found")
stop_at <- grep("^## ", lines[(start + 1L):length(lines)])
end <- if (length(stop_at)) start + stop_at[1L] - 1L else length(lines)
chunk <- lines[(start + 1L):end]
chunk <- chunk[nzchar(chunk)]
header <- grep("^sample\tcell_type\tmatched_core_genes\t", chunk)
if (length(header) != 1L) stop("core-marker header not found")
tab <- read.delim(text = paste(chunk[header:length(chunk)], collapse = "\n"),
                  stringsAsFactors = FALSE, check.names = FALSE)
if (nrow(tab) != 32L || length(unique(tab$cell_type)) != 16L) {
  stop("unexpected core-marker table dimensions")
}

sample_vec <- tab[[1L]]
type_vec <- tab[[2L]]
core2_vec <- as.numeric(tab[[5L]])
